// n8n Error Trigger 受信 → Slack mrkdwn (日本語 + リンク) に整形
// 通知条件: mode が trigger / webhook / retry のみ (manual はスキップ)

const e = $input.first().json;
const exec = e.execution || {};
const wf = e.workflow || {};
const err = exec.error || {};
const wfName = wf.name || '(不明)';
const wfId   = wf.id   || '';
const lastNode = (err.node && err.node.name) ? err.node.name : '(不明)';
const mode = exec.mode || '(不明)';
const execId = exec.id || '?';

const N8N_BASE = 'https://campwill.app.n8n.cloud';
const wfUrl   = wfId ? `${N8N_BASE}/workflow/${wfId}` : N8N_BASE;
const execUrl = exec.url || (wfId ? `${N8N_BASE}/workflow/${wfId}/executions/${execId}` : N8N_BASE);

const rawMessage = (err.message || '(メッセージなし)').substring(0, 800);
const httpCode = err.httpCode || '';
const rawDetail = (err.messages && err.messages[0]) ? String(err.messages[0]).substring(0, 1000) : '';
const hasDetail = rawDetail && rawDetail !== rawMessage;

const now = new Date();
const jst = new Date(now.getTime() + 9 * 60 * 60 * 1000).toISOString().replace('T', ' ').substring(0, 19);

const shouldNotify = mode === 'trigger' || mode === 'webhook' || mode === 'retry';

// Slack mrkdwn 形式
//   * 太字
//   `code`
//   ```code block```
//   <URL|ラベル> でクリッカブルリンク
const text =
  `<!here> 🚨 *n8n ワークフロー失敗*\n` +
  `\n` +
  `📋 *ワークフロー*: <${wfUrl}|${wfName}>\n` +
  `🔧 *失敗ノード*: \`${lastNode}\`\n` +
  `⚡ *モード*: \`${mode}\`${httpCode ? ` · HTTP \`${httpCode}\`` : ''}\n` +
  `🕒 *時刻*: ${jst} JST\n` +
  `\n` +
  `*エラー*\n` +
  '```' + rawMessage + '```' +
  (hasDetail ? `\n*詳細*\n\`\`\`${rawDetail}\`\`\`` : '') +
  `\n\n` +
  `🔎 <${execUrl}|この実行を開く>  ·  📋 <${wfUrl}|ワークフロー一覧へ>`;

return [{
  json: {
    should_notify: shouldNotify,
    text: text
  }
}];
